UPDATE t_admin
SET locked_until = CASE WHEN failed_attempts + 1 >= #{threshold} THEN #{lockUntil} ELSE locked_until END,
    failed_attempts = CASE WHEN failed_attempts + 1 >= #{threshold} THEN 0 ELSE failed_attempts + 1 END,
    updated_at = #{now}
WHERE id = #{id}

UPDATE t_admin
SET password_hash = #{passwordHash},
    must_change_password = 0,
    updated_at = #{now}
WHERE id = #{id}
